        }
    }

    /// `bag_sizes` in shelf.json.
    enum BagSize: String, CaseIterable, Codable, Sendable, VocabularyItem {
        static let namespace: Vocabulary.Namespace = .bagSizes

        case g250 = "g_250"
        case g500 = "g_500"
        case g1000 = "g_1000"

        /// `grams` of each entry.
        var grams: Int {
            switch self {
            case .g250: return 250
            case .g500: return 500
            case .g1000: return 1000
            }
        }
    }

    /// `price_bands` in shelf.json.
    enum PriceBand: String, CaseIterable, Codable, Sendable, VocabularyItem {
        static let namespace: Vocabulary.Namespace = .priceBands

        case under15 = "under_15"
        case from15To30 = "from_15_to_30"
        case from30To45 = "from_30_to_45"
        case from45To60 = "from_45_to_60"
        case from60To80 = "from_60_to_80"
        case from80 = "from_80"

        /// `minimum` of each entry.
        var minimum: Int {
            switch self {
            case .under15: return 0
            case .from15To30: return 15
            case .from30To45: return 30
            case .from45To60: return 45
            case .from60To80: return 60
            case .from80: return 80
            }
        }

        /// `maximum_exclusive` of each entry.
        var maximumExclusive: Int? {
            switch self {
            case .under15: return 15
            case .from15To30: return 30
            case .from30To45: return 45
            case .from45To60: return 60
            case .from60To80: return 80
            case .from80: return nil
            }
        }
    }

    /// The fields of the API's BrewParameters (contracts/openapi.yaml) but `method`,
    /// which `field_rules` in brew.json can rule. The raw value is the API property.
    enum BrewField: String, CaseIterable, Codable, Sendable {
        case doseDg = "dose_dg"
        case waterG = "water_g"
        case waterTempC = "water_temp_c"
        case waterTempSpecial = "water_temp_special"
        case brewTimeS = "brew_time_s"
        case grindNormalised = "grind_normalised"
        case waterType = "water_type"
        case milk = "milk"
        case grinder = "grinder"
        case grindSetting = "grind_setting"

        /// For a field whose value lies on the range of the entry picked in another
        /// field (`grind_setting` on the `scale` of the `grinder`): that field.
        var scaledBy: Vocabulary.BrewField? {
            switch self {
            case .doseDg: return nil
            case .waterG: return nil
            case .waterTempC: return nil
            case .waterTempSpecial: return nil
            case .brewTimeS: return nil
            case .grindNormalised: return nil
            case .waterType: return nil
            case .milk: return nil
            case .grinder: return nil
            case .grindSetting: return .grinder
            }
        }
    }

    /// Every numeric range, as `{ minimum, maximum, multipleOf }` with inclusive bounds.
    enum Ranges {
        /// brew.ranges.dose_g
        static let doseG = VocabularyRange(minimum: 5.0, maximum: 100.0, multipleOf: 0.1)
        /// brew.ranges.water_g
        static let waterG = VocabularyRange(minimum: 10.0, maximum: 1500.0, multipleOf: 1.0)
        /// brew.ranges.water_temp_c
        static let waterTempC = VocabularyRange(minimum: 80.0, maximum: 100.0, multipleOf: 1.0)
        /// brew.ranges.brew_time_s
        static let brewTimeS = VocabularyRange(minimum: 1.0, maximum: 172800.0, multipleOf: 1.0)
        /// brew.ranges.grind_normalised
        static let grindNormalised = VocabularyRange(minimum: 1.0, maximum: 10.0, multipleOf: 0.5)
        /// criteria.scale
        static let scale = VocabularyRange(minimum: 1.0, maximum: 10.0, multipleOf: 0.5)

        /// Every range by its JSON path, `<file>.<key>...`.
        static let all: [String: VocabularyRange] = [
            "brew.ranges.dose_g": doseG,
            "brew.ranges.water_g": waterG,
            "brew.ranges.water_temp_c": waterTempC,
            "brew.ranges.brew_time_s": brewTimeS,
            "brew.ranges.grind_normalised": grindNormalised,
            "criteria.scale": scale,
        ]
    }

    /// Every other single value in the vocabulary files.
    enum Constants {
        /// criteria.buy_again.type
        static let buyAgainType: String = "boolean"
        /// flavour_notes.max_picks
        static let maxPicks: Int = 5
        /// shelf.price_band_basis.currency
        static let priceBandBasisCurrency: String = "EUR"
        /// shelf.price_band_basis.per_grams
        static let priceBandBasisPerGrams: Int = 1000

        /// Every constant by its JSON path, `<file>.<key>...`.
        static let all: [String: JSONValue] = [
            "criteria.buy_again.type": .string("boolean"),
            "flavour_notes.max_picks": .number(5.0),
            "shelf.price_band_basis.currency": .string("EUR"),
            "shelf.price_band_basis.per_grams": .number(1000.0),
        ]
    }
}

extension Vocabulary.Method {
    /// brew.field_rules: the methods each ruled field is allowed with, in the order
    /// of the method list. A field without a rule is allowed with every method.
    static let fieldRules: [Vocabulary.BrewField: [Vocabulary.Method]] = [
        .waterTempC: [.espresso, .v60, .chemex, .kalita, .batchFilter, .aeropress, .frenchPress, .siphon, .fullyAutomatic],
        .waterTempSpecial: [.coldBrew],
        .grinder: [.espresso, .mokaPot, .v60, .chemex, .kalita, .batchFilter, .aeropress, .frenchPress, .coldBrew, .cezve, .siphon],
        .grindSetting: [.espresso, .mokaPot, .v60, .chemex, .kalita, .batchFilter, .aeropress, .frenchPress, .coldBrew, .cezve, .siphon],
    ]

    /// Whether this method allows `field`: the brew form shows it, and the API accepts it.
    func allows(_ field: Vocabulary.BrewField) -> Bool {
        guard let methods = Self.fieldRules[field] else { return true }
        return methods.contains(self)
    }

    /// The fields this method allows, in BrewParameters order.
    var allowedFields: [Vocabulary.BrewField] {
        Vocabulary.BrewField.allCases.filter { allows($0) }
    }
}

/// The languages of contracts/i18n/. Every vocabulary id has a label in each.
enum VocabularyLanguage: String, CaseIterable, Sendable {
    case en = "en"
    case de = "de"

    /// The language used when the device language has no labels.
    static let fallback: VocabularyLanguage = .en
}
